  scrpt[9] = fstr(" VIB V1+V3     ELOSS=  0.275  ", 50)
  scrpt[10] = fstr(" VIB  HAR      ELOSS=  0.405  ", 50)
  scrpt[11] = fstr(" VIB  HAR      ELOSS=  0.545  ", 50)
  scrpt[12] = fstr(" EXC DISOCIATN ELOSS=  9.0    ", 50)
  scrpt[13] = fstr(" EXC DISOCIATN ELOSS= 10.0    ", 50)
  scrpt[14] = fstr(" EXC DISOCIATN ELOSS= 11.0    ", 50)
  scrpt[15] = fstr(" EXC DISOCIATN ELOSS= 11.8    ", 50)
  apop = exp(ein[1] / inpt.akt)
  # WRITE(6,99) APOP
  # 99 FORMAT(3X,'APOP=',D12.3)
  en = -(inpt.estep / 2.0)
  fdo i, 1, inpt.nstep:
    en = en + inpt.estep
    block L30:
      # USE LOG INTERPOLATION FOR ELASTIC
      if en <= xen[2]:
        qela = 2.67e-15
        qmom = 2.67e-15
        break L30
      block L4:
        fdo j, 2, ndata:
          if en <= xen[j]: break L4
        j = ndata
      yxj = ln(yelat[j])
      yxj1 = ln(yelat[j - 1])
      xnj = ln(xen[j])
      xnj1 = ln(xen[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qela = exp(a * ln(en) + b) * 1e-16
      yxj = ln(yxsec[j])
      yxj1 = ln(yxsec[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qmom = exp(a * ln(en) + b) * 1e-16
    peqel[2, i] = 0.5 + (qela - qmom) / qela
    q[2, i] = qela
    q[3, i] = 0.0
    peqel[3, i] = 0.5
    block L200:
      if en < ev[3]: break L200
      block L120:
        fdo j, 2, niond:
          if en <= xion[j]: break L120
        j = niond
      a = (yion[j] - yion[j - 1]) / (xion[j] - xion[j - 1])
      b = (xion[j - 1] * yion[j] - xion[j] * yion[j - 1]) / (xion[j - 1] - xion[j])
      q[3, i] = (a * en + b) * 1e-16
      # USE ANISOTROPIC SCATTERING FOR PRIMARY IONISATION ELECTRON FOR
      # ENERGIES ABOVE 2 * IONISATION ENERGY
      # ANISOTROPIC DISTRIBUTION SAME AS ELASTIC AT ENERGY OFFSET BY
      # IONISATION ENERGY
      if en <= 2.0 * ev[3]: break L200
      peqel[3, i] = peqel[2, i - ioff]
    q[4, i] = 0.0
    qatt[1, i] = q[4, i]
    block L300:
      if en < xatt[1]: break L300
      if en > xatt[natt1]: break L300
      block L220:
        fdo j, 2, natt1:
          if en <= xatt[j]: break L220
        j = natt1
      a = (yatt[j] - yatt[j - 1]) / (xatt[j] - xatt[j - 1])
      b = (xatt[j - 1] * yatt[j] - xatt[j] * yatt[j - 1]) / (xatt[j - 1] - xatt[j])
      q[4, i] = (a * en + b) * 1e-19
      qatt[1, i] = q[4, i]
    q[5, i] = 0.0
    q[6, i] = 0.0
    # V4 + V2 SUPERELASTIC
    qin[1, i] = 0.0
    if not (en <= 0.0):
      block L320:
        fdo j, 2, nvib1:
          if en + ein[2] <= xvib1[j]: break L320
        j = nvib1
      a = (yvib1[j] - yvib1[j - 1]) / (xvib1[j] - xvib1[j - 1])
      b = (xvib1[j - 1] * yvib1[j] - xvib1[j] * yvib1[j - 1]) / (xvib1[j - 1] - xvib1[j])
      efac = sqrt(1.0 - ein[1] / en)
      qin[1, i] = avib1 * ln((efac + 1.0) / (efac - 1.0)) / en
      qin[1, i] = qin[1, i] + (en + ein[2]) * (a * (en + ein[2]) + b) / en
      qin[1, i] = qin[1, i] * apop / (1.0 + apop) * 1e-16
    # V4 + V2
    qin[2, i] = 0.0
    if not (en <= ein[2]):
      block L370:
        fdo j, 2, nvib1:
          if en <= xvib1[j]: break L370
        j = nvib1
      a = (yvib1[j] - yvib1[j - 1]) / (xvib1[j] - xvib1[j - 1])
      b = (xvib1[j - 1] * yvib1[j] - xvib1[j] * yvib1[j - 1]) / (xvib1[j - 1] - xvib1[j])
      efac = sqrt(1.0 - ein[2] / en)
      qin[2, i] = avib1 * ln((1.0 + efac) / (1.0 - efac)) / en
      elf = en - ein[2]
      fwd = ln((en + elf) / (en + elf - 2.0 * sqrt(en * elf)))
      bck = ln((en + elf + 2.0 * sqrt(en * elf)) / (en + elf))
      # RATIO OF MT TO TOTAL X-SECT FOR RESONANCE PART =RAT
      xmt = ((1.5 - fwd / (fwd + bck)) * qin[2, i] + rat * (a * en + b)) * 1e-16
      qin[2, i] = (a * en + b + qin[2, i]) * 1e-16
      peqin[2, i] = 0.5 + (qin[2, i] - xmt) / qin[2, i]
      qin[2, i] = qin[2, i] / (1.0 + apop)
    # V1 + V3
    qin[3, i] = 0.0
    if not (en <= ein[3]):
      block L420:
        fdo j, 2, nvib2:
          if en <= xvib2[j]: break L420
        j = nvib2
      a = (yvib2[j] - yvib2[j - 1]) / (xvib2[j] - xvib2[j - 1])
      b = (xvib2[j - 1] * yvib2[j] - xvib2[j] * yvib2[j - 1]) / (xvib2[j - 1] - xvib2[j])
      efac = sqrt(1.0 - ein[3] / en)
      qin[3, i] = avib2 * ln((1.0 + efac) / (1.0 - efac)) / en
      elf = en - ein[3]
      fwd = ln((en + elf) / (en + elf - 2.0 * sqrt(en * elf)))
      bck = ln((en + elf + 2.0 * sqrt(en * elf)) / (en + elf))
      # RATIO OF MT TO TOTAL X-SECT FOR RESONANCE PART =RAT
      xmt = ((1.5 - fwd / (fwd + bck)) * qin[3, i] + rat * (a * en + b)) * 1e-16
      qin[3, i] = (a * en + b + qin[3, i]) * 1e-16
      peqin[3, i] = 0.5 + (qin[3, i] - xmt) / qin[3, i]
    # VIBRATION HARMONICS 1
    qin[4, i] = 0.0
    if not (en <= ein[4]):
      block L520:
        fdo j, 2, nvib3:
          if en <= xvib3[j]: break L520
        j = nvib3
      a = (yvib3[j] - yvib3[j - 1]) / (xvib3[j] - xvib3[j - 1])
      b = (xvib3[j - 1] * yvib3[j] - xvib3[j] * yvib3[j - 1]) / (xvib3[j - 1] - xvib3[j])
      qin[4, i] = (a * en + b) * 1e-16
    # VIBRATION HARMONICS 2
    qin[5, i] = 0.0
    if not (en <= ein[5]):
      block L620:
        fdo j, 2, nvib4:
          if en <= xvib4[j]: break L620
        j = nvib4
      a = (yvib4[j] - yvib4[j - 1]) / (xvib4[j] - xvib4[j - 1])
      b = (xvib4[j - 1] * yvib4[j] - xvib4[j] * yvib4[j - 1]) / (xvib4[j - 1] - xvib4[j])
      qin[5, i] = (a * en + b) * 1e-16
    # DISOCIATIVE EXCITATION
    qin[6, i] = 0.0
    if not (en <= ein[6]):
      block L820:
        fdo j, 2, ndis1:
          if en <= xdis1[j]: break L820
        j = ndis1
      a = (ydis1[j] - ydis1[j - 1]) / (xdis1[j] - xdis1[j - 1])
      b = (xdis1[j - 1] * ydis1[j] - xdis1[j] * ydis1[j - 1]) / (xdis1[j - 1] - xdis1[j])
      qin[6, i] = (a * en + b) * 1e-16
    # DISOCIATIVE EXCITATION
    qin[7, i] = 0.0
    if not (en <= ein[7]):
      block L870:
        fdo j, 2, ndis2:
          if en <= xdis2[j]: break L870
        j = ndis2
      a = (ydis2[j] - ydis2[j - 1]) / (xdis2[j] - xdis2[j - 1])
      b = (xdis2[j - 1] * ydis2[j] - xdis2[j] * ydis2[j - 1]) / (xdis2[j - 1] - xdis2[j])
      qin[7, i] = (a * en + b) * 1e-16
    # DISOCIATIVE EXCITATION
    qin[8, i] = 0.0
    if not (en <= ein[8]):
      block L920:
        fdo j, 2, ndis3:
          if en <= xdis3[j]: break L920
        j = ndis3
      a = (ydis3[j] - ydis3[j - 1]) / (xdis3[j] - xdis3[j - 1])
      b = (xdis3[j - 1] * ydis3[j] - xdis3[j] * ydis3[j - 1]) / (xdis3[j - 1] - xdis3[j])
      qin[8, i] = (a * en + b) * 1e-16
    # DISOCIATIVE EXCITATION
    qin[9, i] = 0.0
    if not (en <= ein[9]):
      block L970:
        fdo j, 2, ndis4:
          if en <= xdis4[j]: break L970
        j = ndis4
      a = (ydis4[j] - ydis4[j - 1]) / (xdis4[j] - xdis4[j - 1])
      b = (xdis4[j - 1] * ydis4[j] - xdis4[j] * ydis4[j - 1]) / (xdis4[j - 1] - xdis4[j])
      qin[9, i] = (a * en + b) * 1e-16
    q[1, i] = q[2, i] + q[3, i] + q[4, i] + qin[1, i] + qin[2, i] + qin[3, i] + qin[4, i] + qin[5, i] + qin[6, i] + qin[7, i] + qin[8, i] + qin[9, i]
  # SAVE COMPUTE TIME
  if inpt.efinal <= ein[9]: nin = 8
  if inpt.efinal <= ein[8]: nin = 7
  if inpt.efinal <= ein[7]: nin = 6
  if inpt.efinal <= ein[6]: nin = 5
  if inpt.efinal <= ein[5]: nin = 4
  if inpt.efinal <= ein[4]: nin = 3
  if inpt.efinal <= ein[3]: nin = 2
  return
